INSERT OR IGNORE INTO Post (id, title, slug, content, excerpt, featuredImage, type, createdAt, updatedAt) VALUES (5281, 'Chương Trình Từ Thiện 2020 | Chuyến đi vùng cao tặng quà trẻ em nghèo', 'chuong-trinh-tu-thien-2020', '
<p>Chương trình từ thiện 2020 đến vùng Phan Rang &#8211; Ninh Thuận khó khăn với cái nắng và gió gay gắt. Những người dân tộc Raglai sinh sống với kinh tế chủ yếu từ chăn nuôi và trồng trọt. Những đứa bé tay chân lấm tấm nhưng đôi mắt luôn to tròn và nụ cười tươi luôn nở trên môi. Chúng tôi cùng nhau bắt tay làm nên một chuyến đi cực kỳ thành công.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ.jpg" alt="Em nhỏ xinh đẹp nhất vùng Ninh Thuận trong chương trình từ thiện 2020 đầu năm" class="wp-image-5311" srcset="https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ.jpg 1280w, https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ-768x430.jpg 768w, https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ-696x390.jpg 696w, https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ-1068x598.jpg 1068w, https://media.huynhhieutravel.com/từ-sâu-trong-đôi-mắt-em-gái-nhỏ-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Em nhỏ xinh đẹp nhất vùng Ninh Thuận trong chương trình từ thiện 2020 đầu năm</figcaption></figure>



<h2 class="wp-block-heading">Hành trình gắn bó chương trình từ thiện</h2>



<p>Năm 20 tuổi tôi bắt đầu những chuyến đi xa Thiện Nguyện. Ánh mắt của những đứa trẻ thơ luôn cuốn hút tôi đầy ma mị. Sự ngây thơ, hồn nhiên luôn thể hiện trên khuôn mặt như lúc nào cũng lấm tấm bùn đen.</p>



<p>Tôi bắt đầu thích dần những chuyến đi đó. Lao động, góp sức cùng những hoạt động clb từ thiện. Từ việc sắp xếp trò chơi, ẩm thực, xếp quà hay bất cứ việc hậu cần nào. Mọi người đều vui vẻ chung sức cùng nhau.</p>



<p>Huỳnh Hiếu Travel luôn quan niệm đi những <a href="https://www.youtube.com/channel/UCnK4hwds4ADet4e3U2y7A0g">chuyến đi</a> này. Mình không cho nhiều hơn thứ mình nhận được. Từ những nhận thức, từ cái tình đến những kỹ năng khác nhau. Cùng mọi người làm việc.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="853" src="https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn.jpg" alt="Núi Rừng Ninh Thuận" class="wp-image-5306" srcset="https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn.jpg 1280w, https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn-768x512.jpg 768w, https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn-696x464.jpg 696w, https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn-1068x712.jpg 1068w, https://media.huynhhieutravel.com/núi-rừng-ninh-thuạn-630x420.jpg 630w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Núi Rừng Ninh Thuận</figcaption></figure>



<p>&#8220;Năm sau mấy anh lại đến nữa nha!&#8221; Đó là câu nói ấn tượng nhất với tôi trong chuyến đi Ninh Thuận lần này. Buổi tối ngồi sắp lớp trên hành lang dài hát cùng nhau là hoạt động yêu thích nhất với tôi hôm đó. Bài hát chúc mừng sinh nhật một thành viên trong clb là thứ tôi trân quý nhất.</p>



<p>Ngủ có hơi cực 1 tí, tắm có hơi khó 1 tí, ăn có hơi không ngon 1 tí. Nhưng thật sự cảm ơn hành trình mà mọi người CLB Tia Sáng đã gắn bó cùng nhau. Hãy cùng nhau mang lại nhiều điều tuyệt vời hơn nữa.</p>



<h2 class="wp-block-heading">Chương trình từ thiện 2020 Xuân Yêu Thương đến Ninh Thuận</h2>



<p>Chương trình từ thiện bắt đầu với việc chia làm các nhóm: nấu ăn, xếp quà, văn nghệ, team game. Mỗi bộ phận có nhiêm vụ riêng để chuẩn bị một chương trình ý nghĩa vào trưa chiều hôm đó.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1050" height="960" src="https://media.huynhhieutravel.com/bà-cụ-người-Raglai-1050x960.jpg" alt="Bà cụ người Raglai" class="wp-image-5286"/><figcaption>Bà cụ người Raglai</figcaption></figure>



<p>Chương trình từ thiện 2020 xuân yêu thương tổ chức ở thôn Rã Giữa, xã Phước Trung, huyện Bắc Ái, Phan Rang, Ninh Thuận. Một vùng đất nghèo khó mà đời sống người dân làm chăn nuôi, nương rẫy là chủ yếu.</p>



<figure class="wp-block-gallery columns-3 is-cropped wp-block-gallery-1 is-layout-flex wp-block-gallery-is-layout-flex"><ul class="blocks-gallery-grid"><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1280" height="559" src="https://media.huynhhieutravel.com/chăn-dê.jpg" alt="Chăn dê" data-id="5289" data-full-url="https://media.huynhhieutravel.com/chăn-dê.jpg" data-link="https://huynhhieutravel.com/?attachment_id=5289" class="wp-image-5289" srcset="https://media.huynhhieutravel.com/chăn-dê.jpg 1280w, https://media.huynhhieutravel.com/chăn-dê-768x335.jpg 768w, https://media.huynhhieutravel.com/chăn-dê-696x304.jpg 696w, https://media.huynhhieutravel.com/chăn-dê-1068x466.jpg 1068w, https://media.huynhhieutravel.com/chăn-dê-962x420.jpg 962w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="blocks-gallery-item__caption">Chăn dê</figcaption></figure></li><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa.jpg" alt="Người dân làm nông nghiệp là chủ yếu ở thôn Rã Giữa" data-id="5299" data-full-url="https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa.jpg" data-link="https://huynhhieutravel.com/?attachment_id=5299" class="wp-image-5299" srcset="https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa.jpg 1280w, https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa-768x430.jpg 768w, https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa-696x390.jpg 696w, https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa-1068x598.jpg 1068w, https://media.huynhhieutravel.com/người-dân-làm-nông-nghiệp-là-chủ-yếu-ở-thôn-rã-giữa-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="blocks-gallery-item__caption">Người dân làm nông nghiệp là chủ yếu ở thôn Rã Giữa</figcaption></figure></li><li class="blocks-gallery-item"><figure><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận.jpg" alt="Người dân nuôi dê Ninh Thuận" data-id="5300" data-full-url="https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận.jpg" data-link="https://huynhhieutravel.com/?attachment_id=5300" class="wp-image-5300" srcset="https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận.jpg 1280w, https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận-768x430.jpg 768w, https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận-696x390.jpg 696w, https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận-1068x598.jpg 1068w, https://media.huynhhieutravel.com/người-dân-nuôi-dê-ninh-thuận-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption class="blocks-gallery-item__caption">Người dân nuôi dê Ninh Thuận</figcaption></figure></li></ul></figure>



<p>Nhiều người cũng bắt đầu đến sớm để &#8220;nhìn xem&#8221; các anh chị tình nguyện đang làm gì. Từ những bà cụ đến những trẻ em lân cận đều tò mò.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi.jpg" alt="Các em nhỏ chờ đợi tới giờ tổ chức trò chơi ở chương trình từ thiện 2020" class="wp-image-5287" srcset="https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi.jpg 1280w, https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi-768x430.jpg 768w, https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi-696x390.jpg 696w, https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi-1068x598.jpg 1068w, https://media.huynhhieutravel.com/các-em-nhỏ-chờ-đợi-tới-giờ-tổ-chức-trò-chơi-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Các em nhỏ chờ đợi tới giờ tổ chức trò chơi</figcaption></figure>



<p>Những đứa bé vui cười cùng những anh chị đến từ thành phố.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai.jpg" alt="Cậu bé người dân tộc Raglai" class="wp-image-5288" srcset="https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai.jpg 1280w, https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai-768x430.jpg 768w, https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai-696x390.jpg 696w, https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai-1068x598.jpg 1068w, https://media.huynhhieutravel.com/cậu-bé-người-dân-tộc-raglai-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Cậu bé người dân tộc Raglai</figcaption></figure>



<p>Các anh chị chuẩn bị quà mang ra từ xe lớn.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai.jpg" alt="CLB Tia Sáng chuản bị quà tặng chương trình từ thiện 2020 cho các trẻ em Raglai" class="wp-image-5293" srcset="https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai.jpg 1280w, https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai-768x430.jpg 768w, https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai-696x390.jpg 696w, https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai-1068x598.jpg 1068w, https://media.huynhhieutravel.com/clb-tia-sáng-chuẩn-bị-quà-tặng-các-trẻ-em-Raglai-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>CLB Tia Sáng chuản bị quà tặng chương trình từ thiện 2020 cho các trẻ em Raglai</figcaption></figure>



<p>Những người nhiếp ảnh <a href="https://huynhhieutravel.com/cau-lac-bo-tia-sang/" target="_blank" rel="noreferrer noopener" aria-label="clb Tia Sáng (mở trong tab mới)">clb Tia Sáng</a> tranh thủ săn những tấm ảnh đẹp.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/chụp-ảnh.jpg" alt="Chụp ảnh bà cụ ở nơi tổ chức chương trình từ thiện 2020" class="wp-image-5291" srcset="https://media.huynhhieutravel.com/chụp-ảnh.jpg 1280w, https://media.huynhhieutravel.com/chụp-ảnh-768x430.jpg 768w, https://media.huynhhieutravel.com/chụp-ảnh-696x390.jpg 696w, https://media.huynhhieutravel.com/chụp-ảnh-1068x598.jpg 1068w, https://media.huynhhieutravel.com/chụp-ảnh-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Chụp ảnh bà cụ ở nơi từ thiện</figcaption></figure>



<p>Mọi người vừa chuẩn bị chương trình vừa trò chuyện cùng nhau dưới những bóng mát.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây.jpg" alt="CLB Tia Sáng họp nhóm dưới bóng cây" class="wp-image-5292" srcset="https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây.jpg 1280w, https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây-768x430.jpg 768w, https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây-696x390.jpg 696w, https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây-1068x598.jpg 1068w, https://media.huynhhieutravel.com/clb-họp-nhóm-dưới-bóng-cây-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>CLB Tia Sáng họp nhóm dưới bóng cây</figcaption></figure>



<p>Nhiều người chuẩn bị các hoạt động trang trí như cây mai, cây đào cho chương trình dịp xuân đến.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận.jpg" alt="CLB Tia Sáng và công an thôn Rã Giữa ở Ninh Thuận trong chương trình từ thiện 2020" class="wp-image-5294" srcset="https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận.jpg 1280w, https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận-768x430.jpg 768w, https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận-696x390.jpg 696w, https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận-1068x598.jpg 1068w, https://media.huynhhieutravel.com/clb-tia-sáng-và-công-an-thôn-rã-giữa-ở-ninh-thuận-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>CLB Tia Sáng và công an thôn Rã Giữa ở Ninh Thuận</figcaption></figure>



<p>Lếu bạt cỡ lớn cũng được văng ra để che nắng cho các em nhỏ vui chơi.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="853" src="https://media.huynhhieutravel.com/dân-quân-một-lòng.jpg" alt="Dân quân một lòng ở chương trình từ thiện 2020" class="wp-image-5295" srcset="https://media.huynhhieutravel.com/dân-quân-một-lòng.jpg 1280w, https://media.huynhhieutravel.com/dân-quân-một-lòng-768x512.jpg 768w, https://media.huynhhieutravel.com/dân-quân-một-lòng-696x464.jpg 696w, https://media.huynhhieutravel.com/dân-quân-một-lòng-1068x712.jpg 1068w, https://media.huynhhieutravel.com/dân-quân-một-lòng-630x420.jpg 630w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Dân quân một lòng ở chương trình từ thiện 2020</figcaption></figure>



<p>Team game là những người tất bật chuẩn bị chương trình từ thiện 2020 sôi nổi nhất. Họ chuẩn bị các gian hàng trò chơi từ: ném phi tiêu, vẽ tranh, ném vòng, ném banh, bịt mắt đập lon, nhún thú, câu quà, quay vòng có thưởng,&#8230;</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng.jpg" alt="Họp team game CLB Tia Sáng cho chương trình từ thiện 2020" class="wp-image-5296" srcset="https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng.jpg 1280w, https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng-768x430.jpg 768w, https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng-696x390.jpg 696w, https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng-1068x598.jpg 1068w, https://media.huynhhieutravel.com/họp-team-game-clb-tia-sáng-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Họp team game CLB Tia Sáng cho chương trình từ thiện 2020</figcaption></figure>



<p>Nhiều đứa trẻ hồi hộp chờ nhận quà.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="765" src="https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc.jpg" alt="Một cậu bé người dân tộc ở Ninh Thuận" class="wp-image-5298" srcset="https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc.jpg 1280w, https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc-768x459.jpg 768w, https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc-696x416.jpg 696w, https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc-1068x638.jpg 1068w, https://media.huynhhieutravel.com/một-cậu-bé-người-dân-tộc-703x420.jpg 703w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Một cậu bé người dân tộc ở Ninh Thuận</figcaption></figure>



<p>Đặc biệt những chiến binh thiện nguyện clb Tia Sáng cũng có nhiều cô gái xinh đẹp và vô cùng nhiệt tình.</p>



<figure class="wp-block-image size-large"><img loading="lazy" decoding="async" width="1280" height="717" src="https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng.jpg" alt="Những cô gái tình nguyện xinh đẹp của clb Tia Sáng trong chương trình từ thiện 2020" class="wp-image-5301" srcset="https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng.jpg 1280w, https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng-768x430.jpg 768w, https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng-696x390.jpg 696w, https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng-1068x598.jpg 1068w, https://media.huynhhieutravel.com/những-cô-gái-tình-nguyện-xinh-đẹp-của-clb-tia-sáng-750x420.jpg 750w" sizes="(max-width: 1280px) 100vw, 1280px" /><figcaption>Những cô gái tình nguyện xinh đẹp của clb Tia Sáng</figcaption></figure>



<p>Không khí vui tươi cùng những đứa trẻ cùng chương trình từ thiện 2020.</p>



